dashboard.definition:
{
    "title": "Database Performance",
    "description": "Database performance for the CoolaShaker SQL Servers",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "db_host": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_base": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_mssql location=\"$site$\" event_type=performance\n| eval db_host=mvindex(host, 0)\n| bin _time span=5m\n| stats avg(cpu_pct) as cpu avg(memory_mb) as mem avg(transactions_per_sec) as tps avg(batch_requests_per_sec) as batch avg(buffer_cache_hit_ratio) as cache avg(page_life_expectancy) as ple avg(disk_queue_length) as disk_queue avg(lock_waits_per_sec) as lock_waits sum(deadlocks_per_sec) as deadlocks max(active_connections) as connections by _time location db_host",
                "enableSmartSources": true
            },
            "name": "SQL Server performance (5 min)"
        },
        "ds_k_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(cpu) as CPU"
            }
        },
        "ds_k_cache": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(cache) as \"Cache hit\""
            }
        },
        "ds_k_tps": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(tps) as TPS"
            }
        },
        "ds_k_dead": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(deadlocks) as Deadlocks"
            }
        },
        "ds_k_conn": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(connections) as Connections"
            }
        },
        "ds_rings": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats avg(cache) as value avg(ple) as ple by db_host location\n| eval name=db_host, value=round(value, 1), unit=\"%\", min=80, max=100, warn=95, crit=90, better=\"higher\", key=db_host, detail=location.\" · page life \".round(ple, 0).\" s\"\n| table name value unit min max warn crit better detail key"
            }
        },
        "ds_heat_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m limit=0 avg(cpu) by db_host"
            }
        },
        "ds_tps": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| search db_host=\"$db_host$\" | timechart span=5m sum(tps) as \"Transactions/s\" sum(batch) as \"Batch requests/s\""
            }
        },
        "ds_io": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| search db_host=\"$db_host$\" | timechart span=5m avg(disk_queue) as \"Disk queue\" avg(lock_waits) as \"Lock waits/s\" sum(deadlocks) as Deadlocks"
            }
        },
        "ds_overview": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats latest(cpu) as \"CPU %\" latest(mem) as \"Memory MB\" latest(connections) as Connections avg(tps) as \"Avg TPS\" latest(cache) as \"Cache hit %\" latest(ple) as PLE sum(deadlocks) as Deadlocks by location db_host\n| eval \"CPU %\"=round('CPU %', 1), \"Memory MB\"=round('Memory MB', 0), \"Avg TPS\"=round('Avg TPS', 0), \"Cache hit %\"=round('Cache hit %', 1), PLE=round(PLE, 0)\n| rename location as Site db_host as Server"
            }
        },
        "ds_queries": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_mssql location=\"$site$\" event_type=query_performance\n| eval db_host=mvindex(host, 0)\n| search db_host=\"$db_host$\"\n| stats avg(duration_ms) as avg max(duration_ms) as max avg(cpu_time_ms) as cpu avg(logical_reads) as reads count as runs by db_host query\n| sort - max\n| head 10\n| eval avg=round(avg, 0), max=round(max, 0), cpu=round(cpu, 0), reads=round(reads, 0)\n| rename db_host as Server query as Query avg as \"Avg ms\" max as \"Max ms\" cpu as \"CPU ms\" reads as \"Logical reads\" runs as Runs",
                "enableSmartSources": true
            },
            "name": "Slow queries"
        },
        "ds_query_server": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_queries",
                "query": "| stats max(\"Max ms\") as \"Max ms\" by Server | sort - \"Max ms\""
            }
        },
        "ds_waits": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_mssql location=\"$site$\" event_type=wait_stats\n| eval db_host=mvindex(host, 0)\n| stats sum(wait_time_ms) as total sum(waiting_tasks_count) as tasks by wait_type\n| sort - total\n| head 10\n| eval total=round(total / 1000, 1)\n| rename wait_type as \"Wait type\" total as \"Wait time s\" tasks as \"Waiting tasks\"",
                "enableSmartSources": true
            },
            "name": "Wait statistics"
        },
        "ds_logs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_mssql location=\"$site$\" event_type IN (log_status, backup)\n| eval db_host=mvindex(host, 0)\n| stats latest(log_space_used_pct) as log_used latest(log_file_size_mb) as log_size avg(log_growth_rate_mb_per_min) as growth latest(backup_type) as backup_type latest(status) as backup_status latest(duration_sec) as backup_s by location db_host\n| eval \"Log used %\"=round(log_used, 1), \"Log MB\"=round(log_size, 0), \"Growth MB/min\"=round(growth, 1), \"Backup s\"=round(backup_s, 0)\n| table location db_host \"Log used %\" \"Log MB\" \"Growth MB/min\" backup_type backup_status \"Backup s\"\n| rename location as Site db_host as Server backup_type as \"Last backup\" backup_status as \"Backup status\"",
                "enableSmartSources": true
            },
            "name": "Logs and backups"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_exec.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_executive",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_factory": {
            "type": "splunk.image",
