        "viz_sub_cs_database": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/sub_cs_database_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_sub_cs_ai_workload": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/sub_cs_ai_workload.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_ai_workload",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 90,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 90,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cache"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 90,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 90,
                        "to": 95,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 95,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_tps"
            },
            "options": {
                "majorColor": "#eaf2ff",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_conn"
            },
            "options": {
                "majorColor": "#eaf2ff",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_dead"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 6,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 6,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "coolashaker_studio.health_rings",
            "dataSources": {
                "primary": "ds_rings"
            },
            "options": {
                "decimals": 1,
                "drilldownToken": "db_host"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "db_host",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_07": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_cpu"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 70,
                "crit": 90,
                "unit": "%",
                "drilldownToken": "db_host"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "db_host",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_tps"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#2dd4bf",
                    "#a78bfa"
                ],
                "lineWidth": 2
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_io"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#ffc53d",
                    "#60a5fa",
                    "#ff4d6d"
                ],
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_overview"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 6,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "CPU %": {
                        "rowBackgroundColors": "> table | seriesByName(\"CPU %\") | rangeValue(range_2)"
                    },
                    "Cache hit %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Cache hit %\") | rangeValue(range_3)"
                    },
                    "Deadlocks": {
                        "rowBackgroundColors": "> table | seriesByName(\"Deadlocks\") | rangeValue(range_4)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ],
                "range_2": [
                    {
                        "to": 70,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 70,
                        "to": 90,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 90,
                        "value": "#5a1426"
                    }
                ],
                "range_3": [
                    {
                        "to": 90,
                        "value": "#5a1426"
                    },
                    {
                        "from": 90,
                        "to": 95,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 95,
                        "value": "#0d3b2c"
                    }
                ],
                "range_4": [
                    {
                        "to": 1,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 1,
                        "to": 6,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 6,
                        "value": "#5a1426"
                    }
                ]
            }
        },
        "viz_11": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_queries"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
